#!/usr/bin/env bash
# GENERATED by tools/landed_parent/lp.py: lockstep bench dsdv_svc_rs_entry_f (flat) vs dsdv_svc_rs_entry_lp + mutants [1, 2, 3, 4] + region audit.
# Run on the FLEET (ot-run), never on localhost.  Exit 0 iff MUT 0 PASSES, every mutant FAILS and the audit PASSES.
#   bash rtl/dsrom_sys/s81_dv/svc_rs/lp/dsdv_svc_rs_entry_lp_bench.sh OUTDIR        (SIM=iverilog default | verilator; LP_MUTS="0 1" runs a subset,
#   e.g. one fleet job per mutant for big parents -- each subset run checks only its own mutants)
set -u
cd "${LP_ROOT:-$(git -C "$(dirname "$0")" rev-parse --show-toplevel 2>/dev/null || (cd "$(dirname "$0")/../../../../.." && pwd))}"
OUT=${1:-lp_bench_out}; mkdir -p "$OUT"; SIM=${SIM:-iverilog}; rc=0
SRCS="rtl/dsrom_sys/s81_dv/svc_rs/dsdv_svc_rs_entry_f.sv rtl/hdc/v41x/ot_hdc_v41x_attn_tile_s.sv rtl/hdc/v41x/ot_hdc_v41x_attn_s.sv rtl/hdc/v41x/ot_hdc_v41x_kreg.sv rtl/hdc/v41x/ot_hdc_v41x_attn_tile_lat.sv rtl/hdc/v41x/ot_hdc_v41x_attn_tile.sv rtl/hdc/v41x/ot_hdc_v41x_attn.sv rtl/hdc/v41x/ot_hdc_v41x_attn_staging.sv physical/asap7_memory_macros/ot_sram_1r1w_256x256_m2_r2c2/ot_sram_1r1w_256x256_m2_r2c2.v rtl/hdc/ot_hdc_fastfp.sv rtl/hdc/ot_hdc_fp32_add_lat.sv rtl/hdc/ot_hdc_prefix.sv rtl/hdc/ot_hdc_fp32_f12.sv rtl/hdc/v41x/ot_dsrom_su_add6.sv rtl/hdc/ot_hdc_delay.sv rtl/dsrom_sys/s81_ctrl/ot_s81_svc_job.sv rtl/dsrom_sys/s81_ph/svc/dsfd_svc_pc.sv rtl/dsrom_sys/s81_glue/ot_s81_rly.sv rtl/dsrom_sys/s81_glue/dsfd_rly_masters_dv276.sv rtl/dsrom_sys/s81_dv/su_sm/ot_s81_su_sms.sv rtl/dsrom_sys/s81_dv/su_sm/ot_s81_su_smq.sv rtl/dsrom_sys/s81_dv/su_sm/ot_s81_su_smh.sv rtl/dsrom_sys/s81_dv/su_sm/dsfd_su_t_smh.sv rtl/dsrom_sys/s81_dv/su_sm/dsfd_su_t_smhq.sv rtl/dsrom_sys/s81_dv/su_sm/dsfd_su_t_smhr.sv rtl/dsrom_sys/s81_suhc/hier/dsfd_su_t_sm.sv rtl/dsrom_sys/s81_suhc/hier/ot_s81_su_sm.sv rtl/hdc/ot_hdc_fastfp_lat_f12.sv rtl/hdc/ot_hdc_fp32_mul_lat.sv rtl/hdc/ot_hdc_sfu.sv rtl/hdc/v41x/ot_dsrom_fp32_add_l6.sv rtl/hdc/v41x/ot_dsrom_su_f12.sv rtl/hdc/v41x/ot_dsrom_su_fdiv_f12.sv rtl/hdc/v41x/ot_dsrom_su_softmax_add6.sv rtl/hdc/v41x/ot_dsrom_su_softmax_add.sv rtl/hdc/v41x/ot_dsrom_su_softmax_f12r.sv rtl/hdc/v41x/ot_dsrom_su_softmax_m9.sv rtl/hdc/v41x/ot_hdc_v41x_sfu.sv rtl/dsrom_sys/s81_dv/svc_rs/dsdv_svc_sx_hrow.sv rtl/dsrom_sys/s81_dv/svc_rs/dsdv_svc_sx.sv rtl/dsrom_sys/s81_dv/svc_rs/dsdv_svc_att.sv rtl/dsrom_sys/s81_dv/svc_rs/dsdv_svc_rs.sv rtl/dsrom_sys/s81_ph/svc/dsfd_svc_c.sv rtl/dsrom_sys/s81_dv/svc_rs/dsdv_svc_rs_glue.sv rtl/common/landed_parent/ot_pl_land.sv rtl/dsrom_sys/s81_dv/svc_rs/lp/dsdv_svc_rs_entry_lp.sv rtl/dsrom_sys/s81_dv/svc_rs/lp/tb_dsdv_svc_rs_entry_lp.sv"
python3 tools/landed_parent/lp.py audit results/arch/s81_dv_1016/svc_rs/lp/dsdv_svc_rs_entry_lp_spec.json > "$OUT/audit.log" 2>&1 && echo "AUDIT PASS" || { echo "AUDIT FAIL"; rc=1; }
python3 tools/landed_parent/lp.py audit results/arch/s81_dv_1016/svc_rs/lp/dsdv_svc_rs_entry_lp_spec.json --rtl "$OUT/unland.sv" --make-unland > "$OUT/audit_unland.log" 2>&1 \
  && { echo "AUDIT-UNLAND PASSED (should FAIL)"; rc=1; } || echo "AUDIT-UNLAND FAIL (expected)"
for m in ${LP_MUTS:-0 1 2 3 4}; do
  if [ "$SIM" = verilator ]; then
    "${VERILATOR:-verilator}" --binary -j 8 -Wno-fatal -Wno-WIDTH -Wno-TIMESCALEMOD --unroll-count 16 --unroll-limit 131072 --output-split 20000 --output-split-cfuncs 2000 -fno-inline -MAKEFLAGS OPT_SLOW=-O0 -CFLAGS -O1 --top-module tb_dsdv_svc_rs_entry_lp -GMUT=$m -DSU_SMU_T -DSVCQ_ENG_FG3 -Irtl/dsrom_sys/s81_dv/svc_rs $SRCS -Mdir "$OUT/obj$m" > "$OUT/build_$m.log" 2>&1 \
      && "$OUT/obj$m/Vtb_dsdv_svc_rs_entry_lp" > "$OUT/mut$m.log" 2>&1
  else
    iverilog -g2012 -o "$OUT/sim$m" -s tb_dsdv_svc_rs_entry_lp -Ptb_dsdv_svc_rs_entry_lp.MUT=$m -DSU_SMU_T -DSVCQ_ENG_FG3 -Irtl/dsrom_sys/s81_dv/svc_rs $SRCS > "$OUT/build_$m.log" 2>&1 \
      && vvp -n "$OUT/sim$m" > "$OUT/mut$m.log" 2>&1
  fi
  r=$(grep -o 'LP_LOCKSTEP [A-Z]*' "$OUT/mut$m.log" 2>/dev/null | head -1)
  echo "MUT $m: ${r:-NO_RESULT (see $OUT/build_$m.log)}"
  if [ $m -eq 0 ]; then [ "$r" = "LP_LOCKSTEP PASS" ] || rc=1; else [ "$r" = "LP_LOCKSTEP FAIL" ] || rc=1; fi
done
echo "BENCH_EXIT $rc"; exit $rc
